export function getIntegrationLogoUrl(id: string): string | null {
  const key = id.toLowerCase();

  const inline = INLINE[key];
  if (inline) return svgDataUri(inline.path, inline.fill);

  const cdn = CDN_LOGOS[key];
  if (cdn) return `${CDN}/${cdn.slug}/${cdn.color}`;

  if (/^[a-z][a-z0-9]+$/.test(key)) return `${CDN}/${key}/ffffff`;

  return null;
}
